# Production MoE inference configuration (YAML for Triton Inference Server)
# Configuration for serving Mixtral-style MoE model
name: "mixtral_moe"
platform: "pytorch_libtorch"
max_batch_size: 32

instance_group [
  {
    count: 4  # Number of model instances
    kind: KIND_GPU
    gpus: [0, 1, 2, 3]  # Expert placement across GPUs
  }
]

# Expert-aware batching configuration
dynamic_batching {
  preferred_batch_size: [8, 16, 32]
  max_queue_delay_microseconds: 5000

  # Custom batching for MoE: group by expert routing
  priority_levels: 2
  default_priority_level: 1

  # High priority for latency-sensitive requests
  priority_queue_policy {
    key: "priority"
    value: 0
    timeout_action: DELAY
    timeout_microseconds: 1000
  }
}

# Expert caching and memory management
optimization {
  execution_accelerators {
    gpu_execution_accelerator [
      {
        name: "expert_cache"
        parameters {
          key: "cache_experts"
          value: "0,1,2,3"  # Keep first 4 experts in VRAM
        }
        parameters {
          key: "eviction_policy"
          value: "LRU"  # Least Recently Used
        }
      }
    ]
  }
}

# Model parameters specific to MoE
parameters {
  key: "num_experts"
  value: { string_value: "8" }
}
parameters {
  key: "top_k"
  value: { string_value: "2" }
}
parameters {
  key: "expert_parallel"
  value: { string_value: "true" }
}
